561	  public async close() {
562	    // Flip into the shutting-down state even when "return503OnClosing" is
563	    // not enabled (mirroring the Express adapter); the flag is only
564	    // observed by the request gate installed for that option.
565	    this.isShuttingDown = true;
566	    // Cache the close operation so that repeated "app.close()" calls (the
567	    // core allows a shutdown cycle to run again once the previous one has
568	    // settled) neither close the underlying instance twice nor re-open the
569	    // request gate.
570	    this.closePromise ??= this.closeInstance();
571	    return this.closePromise;
572	  }
